from __future__ import annotations
from pathlib import Path
import sys
root=Path(sys.argv[1] if len(sys.argv)>1 else 'v1.1/base').resolve()

def one(s,old,new,label):
    if old not in s:raise SystemExit(f'anchor missing: {label}')
    return s.replace(old,new,1)

p=root/'static/app.js';s=p.read_text(encoding='utf-8')
s=one(s,"async function api(path,opt={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});if(!r.ok){let x;try{x=await r.json()}catch{x={detail:await r.text()}}throw new Error(x.detail||r.statusText)}return r.headers.get('content-type')?.includes('json')?r.json():r;}","async function api(path,opt={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});if(!r.ok){let x;try{x=await r.json()}catch{x={detail:await r.text()}}throw new Error(x.detail||r.statusText)}return r.headers.get('content-type')?.includes('json')?r.json():r;}\nasync function apiForm(path,form){const r=await fetch(path,{method:'POST',body:form});if(!r.ok){let x;try{x=await r.json()}catch{x={detail:await r.text()}}throw new Error(x.detail||r.statusText)}return r.json();}",'form api')
old="""function renderInspector(){const el=$('#inspectorBody');const o=S.project?.objects.find(x=>x.id===S.selected);if(!o){el.innerHTML='<div class=\"assistantMsg\">Select a part or real-world component to inspect and edit its canonical parameters.</div>';return}const p=o.params||{},t=o.transform||{};el.innerHTML=`
<div class=\"field\"><label>Name</label><input data-field=\"name\" value=\"${esc(o.name)}\"></div><div class=\"field\"><label>Material</label><select data-field=\"material\">${Object.entries(window._materials||{}).map(([k,v])=>`<option value=\"${k}\" ${k===o.material?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>
<div class=\"groupTitle\">GEOMETRY</div>${Object.entries(p).filter(([k,v])=>typeof v==='number').map(([k,v])=>`<div class=\"field\"><label>${esc(k)} (mm)</label><input type=\"number\" step=\"0.1\" data-param=\"${esc(k)}\" value=\"${v}\"></div>`).join('')}
<div class=\"groupTitle\">POSITION</div>${['x','y','z'].map((k,i)=>`<div class=\"field\"><label>${k.toUpperCase()} (mm)</label><input type=\"number\" step=\"0.5\" data-pos=\"${i}\" value=\"${t.position?.[i]||0}\"></div>`).join('')}
${o.component_ref?`<div class=\"groupTitle\">REAL COMPONENT</div><div class=\"assistantMsg\">${esc(o.component_ref)}${o.code?'<br><span class=\"okText\">Programmable • Code workspace attached</span>':''}</div>`:''}<div class=\"groupTitle\">FEATURES</div><button id=\"holeBtn\">＋ Through hole</button> <button id=\"deleteBtn\">Delete object</button>`;
 el.querySelector('[data-field=\"name\"]')?.addEventListener('change',e=>updateObject({name:e.target.value}));el.querySelector('[data-field=\"material\"]')?.addEventListener('change',e=>updateObject({material:e.target.value}));$$('[data-param]').forEach(x=>x.addEventListener('change',e=>{const params={...o.params,[e.target.dataset.param]:Number(e.target.value)};updateObject({params})}));$$('[data-pos]').forEach(x=>x.addEventListener('change',e=>{const pos=[...(o.transform.position||[0,0,0])];pos[Number(e.target.dataset.pos)]=Number(e.target.value);updateTransform(o.id,pos,o.transform.rotation_deg||[0,0,0],true)}));$('#holeBtn')?.addEventListener('click',()=>addHole(o));$('#deleteBtn')?.addEventListener('click',()=>deleteObject(o));
}
"""
new="""function renderInspector(){const el=$('#inspectorBody');const o=S.project?.objects.find(x=>x.id===S.selected);if(!o){el.innerHTML='<div class=\"assistantMsg\">Select a custom part or purchased component. Purchased geometry is immutable vendor data; position, mating and explicit registry sync remain editable.</div>';return}const p=o.params||{},t=o.transform||{},c=o.component_snapshot||null,isComponent=o.kind==='component',connected=new Set((S.project.connections||[]).flatMap(x=>[x.a,x.b]).filter(Boolean).filter(x=>x.object_id===o.id).map(x=>x.interface_id));const geometry=isComponent?`<div class=\"groupTitle\">PURCHASED GEOMETRY</div><div class=\"assistantMsg\">${esc(c?.manufacturer||'Unknown')} ${esc(c?.model||'')}<br>${esc(c?.dimensions_mm?.join(' × ')||'?')} mm • ${c?.mass_g??'?'} g<br><span class=\"fidelityBadge\">${esc(c?.geometry?.fidelity||'unknown')} geometry</span> <span class=\"trustBadge\">trust ${c?.trust_score??0}/100</span><br><small>Vendor/purchased dimensions are read-only. Replace or sync the component instead of deforming it.</small></div>`:`<div class=\"groupTitle\">GEOMETRY</div>${Object.entries(p).filter(([k,v])=>typeof v==='number').map(([k,v])=>`<div class=\"field\"><label>${esc(k)} (mm)</label><input type=\"number\" step=\"0.1\" data-param=\"${esc(k)}\" value=\"${v}\"></div>`).join('')}`;const interfaces=isComponent?`<div class=\"groupTitle\">INTERFACES</div><div class=\"interfaceList\">${(o.interfaces||[]).map(i=>`<div class=\"interfaceRow\"><b>${esc(i.id)}</b><span>${esc(i.kind)}</span><span class=\"${connected.has(i.id)?'okText':'treeMeta'}\">${connected.has(i.id)?'connected':(i.required?'required • open':'open')}</span></div>`).join('')||'<span class=\"treeMeta\">No semantic interfaces defined</span>'}</div><button id=\"mateBtn\">Mate / connect…</button> <button id=\"syncComponentBtn\">Sync registry snapshot</button>`:'';el.innerHTML=`<div class=\"field\"><label>Name</label><input data-field=\"name\" value=\"${esc(o.name)}\"></div>${isComponent?'':`<div class=\"field\"><label>Material</label><select data-field=\"material\">${Object.entries(window._materials||{}).map(([k,v])=>`<option value=\"${k}\" ${k===o.material?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>`}${geometry}<div class=\"groupTitle\">POSITION</div>${['x','y','z'].map((k,i)=>`<div class=\"field\"><label>${k.toUpperCase()} (mm)</label><input type=\"number\" step=\"0.5\" data-pos=\"${i}\" value=\"${t.position?.[i]||0}\"></div>`).join('')}${isComponent?`<div class=\"groupTitle\">REGISTRY ID</div><div class=\"assistantMsg\">${esc(o.component_ref)}${o.code?'<br><span class=\"okText\">Programmable • Code workspace attached</span>':''}</div>${interfaces}`:`<div class=\"groupTitle\">FEATURES</div><button id=\"holeBtn\">＋ Through hole</button>`} <button id=\"deleteBtn\">Delete object</button>`;el.querySelector('[data-field=\"name\"]')?.addEventListener('change',e=>updateObject({name:e.target.value}));el.querySelector('[data-field=\"material\"]')?.addEventListener('change',e=>updateObject({material:e.target.value}));$$('[data-param]').forEach(x=>x.addEventListener('change',e=>{const params={...o.params,[e.target.dataset.param]:Number(e.target.value)};updateObject({params})}));$$('[data-pos]').forEach(x=>x.addEventListener('change',e=>{const pos=[...(o.transform.position||[0,0,0])];pos[Number(e.target.dataset.pos)]=Number(e.target.value);updateTransform(o.id,pos,o.transform.rotation_deg||[0,0,0],true)}));$('#holeBtn')?.addEventListener('click',()=>addHole(o));$('#mateBtn')?.addEventListener('click',()=>mateSelected(o));$('#syncComponentBtn')?.addEventListener('click',async()=>{await api('/api/components/sync/'+o.id,{method:'POST'});await refresh({geometry:true})});$('#deleteBtn')?.addEventListener('click',()=>deleteObject(o));}
async function mateSelected(source){const targets=S.project.objects.filter(x=>x.kind==='component'&&x.id!==source.id);if(!targets.length)return alert('Add another real-world component first.');const target=targets[0];const compatible=[];for(const si of source.interfaces||[])for(const ti of target.interfaces||[]){compatible.push([si,ti])}showModal('Mate / connect component interfaces',`<div class=\"assistantMsg\">Source: <b>${esc(source.name)}</b></div><div class=\"field\"><label>Target</label><select id=\"mateTarget\">${targets.map(x=>`<option value=\"${x.id}\">${esc(x.name)}</option>`).join('')}</select></div><div class=\"field\"><label>Source interface</label><select id=\"mateSourceIf\">${(source.interfaces||[]).map(i=>`<option value=\"${esc(i.id)}\">${esc(i.id)} • ${esc(i.kind)}</option>`).join('')}</select></div><div class=\"field\"><label>Target interface</label><select id=\"mateTargetIf\"></select></div><div class=\"field\"><label>Gap (mm)</label><input id=\"mateGap\" type=\"number\" step=\"0.1\" value=\"0\"></div><button id=\"mateApply\" class=\"primary\">Validate + mate</button>`);const fill=()=>{const t=S.project.objects.find(x=>x.id===$('#mateTarget').value);$('#mateTargetIf').innerHTML=(t?.interfaces||[]).map(i=>`<option value=\"${esc(i.id)}\">${esc(i.id)} • ${esc(i.kind)}</option>`).join('')};$('#mateTarget').onchange=fill;fill();$('#mateApply').onclick=async()=>{try{await api('/api/assembly/mate',{method:'POST',body:JSON.stringify({source_id:source.id,source_interface:$('#mateSourceIf').value,target_id:$('#mateTarget').value,target_interface:$('#mateTargetIf').value,gap_mm:Number($('#mateGap').value)})});$('#modal').classList.add('hidden');await refresh({geometry:true})}catch(e){alert(e.message)}}}
"""
s=one(s,old,new,'inspector')
s=one(s,"function renderMetrics(){const m=S.metrics?.project||{};$('#metricsBody').innerHTML=`<div class=\"metricGrid\"><div class=\"metricCard\"><strong>${(m.mass_kg||0).toFixed(3)}</strong><span>kg total mass</span></div><div class=\"metricCard\"><strong>${m.object_count||0}</strong><span>objects</span></div><div class=\"metricCard\"><strong>${S.project?.simulations?.filter(x=>!x.stale).length||0}</strong><span>current analyses</span></div><div class=\"metricCard\"><strong>${S.project?.simulations?.filter(x=>x.stale).length||0}</strong><span>stale analyses</span></div></div>`}","function renderMetrics(){const m=S.metrics?.project||{};$('#metricsBody').innerHTML=`<div class=\"metricGrid\"><div class=\"metricCard\"><strong>${(m.mass_kg||0).toFixed(3)}</strong><span>kg total mass</span></div><div class=\"metricCard\"><strong>${m.purchased_component_count||0}</strong><span>purchased components</span></div><div class=\"metricCard\"><strong>${m.custom_part_count||0}</strong><span>custom parts</span></div><div class=\"metricCard\"><strong>${m.connection_count||0}</strong><span>interface connections</span></div></div>`}",'metrics')
old="""async function renderComponents(){const el=$('#dockBody');el.innerHTML=`<div class=\"componentToolbar\"><input id=\"componentSearch\" placeholder=\"Search 238 real components — solenoid, bearing, Pi, NEMA 17…\" value=\"${esc(S.componentQuery)}\"><select id=\"componentCategory\"><option value=\"\">All categories</option></select><button id=\"componentGo\">Search</button></div><div id=\"componentGrid\" class=\"componentGrid\"><span class=\"badge\">Loading…</span></div>`;const all=await api('/api/components');const sel=$('#componentCategory');for(const c of all.categories)sel.insertAdjacentHTML('beforeend',`<option ${S.componentCategory===c?'selected':''} value=\"${c}\">${c.replaceAll('_',' ')}</option>`);async function go(){S.componentQuery=$('#componentSearch').value;S.componentCategory=$('#componentCategory').value;const r=await api('/api/components/search',{method:'POST',body:JSON.stringify({query:S.componentQuery,category:S.componentCategory||null,limit:24,include_infeasible:true})});$('#componentGrid').innerHTML=r.results.map(c=>`<div class=\"componentCard\"><strong>${esc(c.name)}</strong><button data-add=\"${esc(c.id)}\">Add</button><small>${esc(c.category)} • ${c.dimensions_mm?.join(' × ')||'?'} mm${c.mass_g!=null?' • '+c.mass_g+' g':''}</small></div>`).join('')||'<span class=\"badge\">No matches</span>';$$('[data-add]').forEach(b=>b.onclick=async()=>{await api('/api/components/add/'+encodeURIComponent(b.dataset.add),{method:'POST'});await refresh({geometry:true})})}$('#componentGo').onclick=go;$('#componentSearch').onkeydown=e=>{if(e.key==='Enter')go()};go()}
"""
new="""async function renderComponents(){const el=$('#dockBody');const all=await api('/api/components');el.innerHTML=`<div class=\"componentRegistryHead\"><div><b>${all.total} component definitions</b><small> • ${all.stats.custom} local/custom • provenance + geometry fidelity tracked</small></div><div><button id=\"realityBtn\">Reality check</button><button id=\"importPackBtn\">Import catalog pack…</button><input id=\"catalogPackFile\" type=\"file\" accept=\".json,.zip\" hidden></div></div><div class=\"componentToolbar\"><input id=\"componentSearch\" placeholder=\"Search real hardware — solenoid, bearing, Pi, NEMA 17…\" value=\"${esc(S.componentQuery)}\"><select id=\"componentCategory\"><option value=\"\">All categories</option></select><button id=\"componentGo\">Search</button></div><div id=\"componentGrid\" class=\"componentGrid\"><span class=\"badge\">Loading…</span></div>`;const sel=$('#componentCategory');for(const c of all.categories)sel.insertAdjacentHTML('beforeend',`<option ${S.componentCategory===c?'selected':''} value=\"${c}\">${c.replaceAll('_',' ')}</option>`);async function go(){S.componentQuery=$('#componentSearch').value;S.componentCategory=$('#componentCategory').value;const r=await api('/api/components/search',{method:'POST',body:JSON.stringify({query:S.componentQuery,category:S.componentCategory||null,limit:30,include_infeasible:true})});$('#componentGrid').innerHTML=r.results.map(c=>`<div class=\"componentCard\"><strong>${esc(c.name)}</strong><button data-add=\"${esc(c.id)}\">Add</button><small>${esc(c.category)} • ${c.dimensions_mm?.join(' × ')||'?'} mm${c.mass_g!=null?' • '+c.mass_g+' g':''}${c.manufacturer_part_number?' • '+esc(c.manufacturer_part_number):''}</small><small><span class=\"fidelityBadge\">${esc(c.geometry?.fidelity||'unknown')}</span> <span class=\"trustBadge\">trust ${c.trust_score??0}</span> • ${(c.interfaces||[]).length} interfaces</small></div>`).join('')||'<span class=\"badge\">No matches</span>';$$('[data-add]').forEach(b=>b.onclick=async()=>{await api('/api/components/add/'+encodeURIComponent(b.dataset.add),{method:'POST'});await refresh({geometry:true})})}$('#componentGo').onclick=go;$('#componentSearch').onkeydown=e=>{if(e.key==='Enter')go()};$('#realityBtn').onclick=runRealityCheck;$('#importPackBtn').onclick=()=>$('#catalogPackFile').click();$('#catalogPackFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const r=await apiForm('/api/components/import-pack',fd);alert(`Imported ${r.added?.length||0} components${r.assets_imported!=null?' and '+r.assets_imported+' assets':''}.`);renderComponents()}catch(err){alert(err.message)}};go()}
async function runRealityCheck(){const r=await api('/api/reality-check');showModal(`Reality check • ${r.counts.error} errors • ${r.counts.warning} warnings`,r.risks.length?r.risks.map(x=>`<div class=\"diffItem\"><b>${esc(x.severity.toUpperCase())}</b> — ${esc(x.message)}</div>`).join(''):'<p class=\"okText\">No component-system issues detected by the current checks.</p>')}
"""
s=one(s,old,new,'component dock')
p.write_text(s,encoding='utf-8')

css=root/'static/styles.css';c=css.read_text(encoding='utf-8');c+='''\n/* ForgeCAD v1.1 real-world component surfaces */\n.fidelityBadge,.trustBadge{display:inline-block;padding:2px 6px;border:1px solid var(--line,#34414b);border-radius:999px;font-size:10px;letter-spacing:.03em;text-transform:uppercase}.trustBadge{opacity:.85}.interfaceList{display:flex;flex-direction:column;gap:5px;margin:6px 0 9px}.interfaceRow{display:grid;grid-template-columns:1fr 1.1fr 1fr;gap:6px;font-size:11px;padding:6px;border:1px solid var(--line,#303941);border-radius:5px}.componentRegistryHead{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:8px}.componentCard small{display:block;margin-top:4px}.componentCard{min-height:82px}\n''';css.write_text(c,encoding='utf-8')
